/// A type that can report raw audio session activity as a boolean stream.
///
/// Conformed to by AudioSessionDetector. Declared in Domain so that
/// CalendarAwareMeetingDetector (Record-ML) can depend on it without importing
/// audio-specific infrastructure.
public protocol AudioActivityObserver: Sendable {
    func rawAudioChanges() -> AsyncStream<Bool>
}

