import Foundation

public struct SummaryConfig: Sendable, Codable, Equatable {
    public let modelId: ModelID
    public let maxTokens: Int
    public let temperature: Double
    public let enabled: Bool
    public let meetingType: MeetingType
    /// Total token budget for the model (prompt + generation). Used to reject
    /// transcripts that would overflow. Gemma 4 4B supports 8192; larger models
    /// (Llama 3.2, Mistral) support 32K–128K — set appropriately per model.
    public let contextWindow: Int

    /// Gemma 4 4B 4-bit — high quality summarization on Apple Silicon via MLX.
    /// Pre-loaded at app startup so summarization is instant when triggered.
    public static let `default` = SummaryConfig(
        modelId: ModelID("mlx-community/gemma-4-e4b-it-4bit"),
        maxTokens: 2048,
        temperature: 0.3,
        enabled: true,
        meetingType: .oneOnOne,
        contextWindow: 8192
    )

    public init(
        modelId: ModelID,
        maxTokens: Int,
        temperature: Double,
        enabled: Bool,
        meetingType: MeetingType,
        contextWindow: Int = 8192
    ) {
        self.modelId = modelId
        self.maxTokens = maxTokens
        self.temperature = temperature
        self.enabled = enabled
        self.meetingType = meetingType
        self.contextWindow = contextWindow
    }

    public init(from decoder: Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        modelId = try container.decode(ModelID.self, forKey: .modelId)
        maxTokens = try container.decode(Int.self, forKey: .maxTokens)
        temperature = try container.decode(Double.self, forKey: .temperature)
        enabled = try container.decode(Bool.self, forKey: .enabled)
