import ArgumentParser
import Domain
import Foundation
import AudioInfrastructure
import MLInfrastructure

@main
struct ProofHarness: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "proof",
        abstract: "THE RECORD — Pipeline Proof Harness",
        subcommands: [Run.self, RunAll.self, List.self, SummarizeText.self],
        defaultSubcommand: List.self
    )
}

// MARK: - Run text-only summary

struct SummarizeText: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "summarize-text",
        abstract: "Run the MLX Summarizer on a JSON text fixture"
    )

    @Argument(help: "Path to a JSON file containing the transcript")
    var jsonFile: String

    @Option(name: .long, help: "Summary model HF slug (default: gemma-4-e4b-it-4bit)")
    var model: String?

    func run() async throws {
        Term.banner()
        let url = URL(fileURLWithPath: jsonFile)
        guard FileManager.default.fileExists(atPath: url.path) else {
            Term.error("File not found: \(jsonFile)")
            throw ExitCode.failure
        }

        let data = try Data(contentsOf: url)
        guard let json = try JSONSerialization.jsonObject(with: data) as? [String: Any],
              let transcript = json["transcript"] as? String
        else {
            Term.error("Invalid JSON format. Expected {\"transcript\": \"...\"}")
            throw ExitCode.failure
        }

        Term.header("SUMMARIZING: \(url.lastPathComponent)")

        let sumConfig: SummaryConfig
        if let modelSlug = model {
            sumConfig = SummaryConfig(
                modelId: ModelID(modelSlug),
                maxTokens: 2048,
                temperature: 0.3,
                enabled: true,
                meetingType: SummaryConfig.default.meetingType,
                contextWindow: 262_144
            )
        } else {
            sumConfig = SummaryConfig.default
        }

        let summarizer = XGrammarSummarizationPlugin()

        Term.progress("Loading \(sumConfig.modelId.rawValue)...")
        let t0 = CFAbsoluteTimeGetCurrent()
        if !(await summarizer.isReady()) {
            try await summarizer.loadModel(sumConfig)
        }
        Term.progressDone(CFAbsoluteTimeGetCurrent() - t0)

        Term.progress("Summarizing...")
        let t1 = CFAbsoluteTimeGetCurrent()

        do {
            let result = try await summarizer.summarize(transcript: transcript, speakers: [])
            let sTime = CFAbsoluteTimeGetCurrent() - t1
            Term.progressDone(sTime)

            print("\n\(Term.bold)SUMMARY:\(Term.reset)")
            print(result.summary)

            print("\n\(Term.bold)GROUND TRUTH:\(Term.reset)")
            print((json["ground_truth_summary"] as? String) ?? "None")

            let timeStr = String(format: "%.1f", sTime)
            Term.success("Completed in \(timeStr)s")
        } catch {
            Term.progressDone(CFAbsoluteTimeGetCurrent() - t1)
            Term.error("Summarization failed: \(error)")
            throw ExitCode.failure
        }
    }
}

// MARK: - Run a single WAV

struct Run: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "Run the pipeline on a single WAV file"
    )

    @Argument(help: "Path to a WAV file (16-bit PCM, any sample rate)")
    var wavFile: String

    @Flag(name: .long, help: "Skip the summarization stage")
    var skipSummary: Bool = false

    @Option(name: .long, help: "Quality: fast (Parakeet), high (two-pass), max (WhisperKit only)")
    var quality: String = "fast"

    @Option(name: .long, help: "Summary model HF slug (default: gemma-4-e4b-it-4bit)")
    var model: String?

    func run() async throws {
        Term.banner()
        let url = URL(fileURLWithPath: wavFile)
        guard FileManager.default.fileExists(atPath: url.path) else {
            Term.error("File not found: \(wavFile)")
            throw ExitCode.failure
        }
        guard let q = Quality(rawValue: quality) else {
            Term.error("Invalid quality: \(quality). Use: fast, high, or max")
            throw ExitCode.failure
        }

        Term.header("PIPELINE: \(url.lastPathComponent)")
        let runner = PipelineRunner()
        let result = try await runner.run(wavURL: url, quality: q, skipSummary: skipSummary, summaryModelId: model)
        ResultPrinter.print(result: result, file: url.lastPathComponent)
        Term.success("Pipeline complete")
    }
}

// MARK: - Run all fixtures

struct RunAll: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        commandName: "all",
        abstract: "Run the pipeline on all diarization fixtures"
    )

    @Flag(name: .long, help: "Skip the summarization stage")
    var skipSummary: Bool = false

    @Option(name: .long, help: "Quality: fast (Parakeet), high (two-pass), max (WhisperKit only)")
    var quality: String = "fast"

    @Option(name: .long, help: "Summary model HF slug (default: gemma-4-e4b-it-4bit)")
    var model: String?

    @Option(name: .long, help: "Path to fixtures directory")
    var fixturesDir: String = "Data/diarization-fixtures"

    func run() async throws {
        Term.banner()
        guard let q = Quality(rawValue: quality) else {
            Term.error("Invalid quality: \(quality). Use: fast, high, or max")
            throw ExitCode.failure
        }

        let dir = URL(fileURLWithPath: fixturesDir)
        let wavFiles = try FileManager.default
            .contentsOfDirectory(at: dir, includingPropertiesForKeys: nil)
            .filter { $0.pathExtension == "wav" }
            .sorted(by: { $0.lastPathComponent < $1.lastPathComponent })

        guard !wavFiles.isEmpty else {
            Term.error("No WAV files found in \(fixturesDir)")
            Term.info("Run", "uv run scripts/download-diarization-fixtures.py")
            throw ExitCode.failure
        }

        print("\(Term.bold)Found \(wavFiles.count) fixtures (quality: \(q.rawValue)):\(Term.reset)")
        for f in wavFiles {
            let size = (try? FileManager.default.attributesOfItem(atPath: f.path)[.size] as? Int) ?? 0
            Term.info(f.lastPathComponent, "\(size / 1024 / 1024) MB")
        }

        let runner = PipelineRunner()
        var totalElapsed: TimeInterval = 0
        var allResults: [PipelineResult] = []
        var allFiles: [String] = []

        for (i, wav) in wavFiles.enumerated() {
            Term.header("[\(i + 1)/\(wavFiles.count)] \(wav.lastPathComponent)")
            let result = try await runner.run(wavURL: wav, quality: q, skipSummary: skipSummary, summaryModelId: model)
            ResultPrinter.print(result: result, file: wav.lastPathComponent)
            allResults.append(result)
            allFiles.append(wav.lastPathComponent)
            totalElapsed += result.totalTime
        }

        let reportPath = "\(fixturesDir)/proof-report.html"
        WebReport.generate(results: allResults, files: allFiles, outputPath: reportPath)

        for (i, result) in allResults.enumerated() {
            let turns = ConversationFormatter.format(segments: result.diarizedSegments)
            let name = allFiles[i].replacingOccurrences(of: ".wav", with: "")
            ChatViewReport.generate(
                turns: turns, fileName: name,
                outputPath: "\(fixturesDir)/chat-\(name).html"
            )
        }

        Term.header("ALL DONE")
        Term.metric("Fixtures processed", "\(wavFiles.count)")
        Term.metric("Quality", q.rawValue)
        Term.metric("Web report", reportPath)
        Term.metric("Total wall time", String(format: "%.1fs (%.1f min)", totalElapsed, totalElapsed / 60))
        Term.success("All pipelines passed")
    }
}

// MARK: - List available fixtures

struct List: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "List available diarization fixtures"
    )

    @Option(name: .long, help: "Path to fixtures directory")
    var fixturesDir: String = "Data/diarization-fixtures"

    func run() async throws {
        Term.banner()

        let dir = URL(fileURLWithPath: fixturesDir)
        guard FileManager.default.fileExists(atPath: dir.path) else {
            Term.error("Fixtures directory not found: \(fixturesDir)")
            Term.info("Run", "uv run scripts/download-diarization-fixtures.py")
            return
        }

        let files = try FileManager.default
            .contentsOfDirectory(at: dir, includingPropertiesForKeys: [.fileSizeKey])
            .sorted(by: { $0.lastPathComponent < $1.lastPathComponent })

        let wavFiles = files.filter { $0.pathExtension == "wav" }
        let rttmFiles = files.filter { $0.pathExtension == "rttm" }
        let jsonFiles = files.filter { $0.pathExtension == "json" }

        Term.header("FIXTURES")
        for wav in wavFiles {
            let size = (try? FileManager.default.attributesOfItem(atPath: wav.path)[.size] as? Int) ?? 0
            let name = wav.deletingPathExtension().lastPathComponent
            let hasRTTM = rttmFiles.contains { $0.deletingPathExtension().lastPathComponent == name }
            let hasJSON = jsonFiles.contains { $0.deletingPathExtension().lastPathComponent == name }
            let rttmBadge = hasRTTM ? "\(Term.green)rttm\(Term.reset)" : "\(Term.red)no rttm\(Term.reset)"
            let jsonBadge = hasJSON ? "\(Term.green)json\(Term.reset)" : "\(Term.red)no json\(Term.reset)"
            print("  \(Term.bold)\(wav.lastPathComponent)\(Term.reset)  \(size / 1024 / 1024) MB  [\(rttmBadge)] [\(jsonBadge)]")
        }

        print("\n\(Term.bold)Usage:\(Term.reset)")
        print("  swift run ProofHarness run <wav> [--quality fast|high|max] [--skip-summary]")
        print("  swift run ProofHarness run <wav> --model mlx-community/gemma-4-26b-a4b-it-4bit")
        print("  swift run ProofHarness all [--quality fast|high|max] [--model <hf-slug>]")
        print("  swift run ProofHarness spike-apple <wav>")
    }
}

