import Domain
import Foundation
import Logging
import OSLog

/// A token representing an active profiling interval.
public struct BoundaryToken: Sendable {
    public let state: OSSignpostIntervalState
    public let startSnapshot: ProcessSnapshot?
    public let name: StaticString
}

/// Wraps OSSignposter with SystemHardwarePoller to capture CPU and GPU metrics
/// at strategic execution boundaries.
public actor HardwareBoundaryProfiler {
    private let poller: SystemHardwarePollerProtocol
    private let signposter: OSSignposter

    public init(category: String, poller: SystemHardwarePollerProtocol = SystemHardwarePoller()) {
        self.poller = poller
        self.signposter = AppLogger.signposter(category: category)
    }

    /// Begins a profiling interval, capturing initial hardware state.
    public func begin(_ name: StaticString) async -> BoundaryToken {
        let state = signposter.beginInterval(name, id: signposter.makeSignpostID())
        let snapshot = await poller.captureProcessSnapshot()
        return BoundaryToken(state: state, startSnapshot: snapshot, name: name)
    }

    /// Ends a profiling interval, calculating hardware deltas and emitting the signpost.
    public func end(_ token: BoundaryToken) async {
        let endSnapshot = await poller.captureProcessSnapshot()
        let mlxMemory = await poller.getMlxMemoryUsageBytes()

        if let start = token.startSnapshot, let end = endSnapshot {
            let cpuUtil = await poller.calculateCpuUtilization(from: start.cpu, to: end.cpu)
            let memDiff = end.memoryMB - start.memoryMB
            let cpuPercent = cpuUtil * 100.0

            let msg = "CPU Util: \(String(format: "%.1f", cpuPercent))% | Mem Δ: \(memDiff) MB | GPU Peak: \(mlxMemory) bytes"
            print("[TELEMETRY] \(token.name) => \(msg)")
            signposter.endInterval(
                token.name,
                token.state,
                "CPU Util: \(cpuPercent, format: .fixed(precision: 1))% | Mem Δ: \(memDiff) MB | GPU Peak: \(mlxMemory) bytes"
            )
        } else {
            signposter.endInterval(token.name, token.state)
        }
    }

    /// Emits a point-in-time snapshot event without an interval.
    public func emitSnapshotEvent(_ name: StaticString) async {
        guard let snap = await poller.captureProcessSnapshot() else { return }
        let mlxMemory = await poller.getMlxMemoryUsageBytes()
        let msg = "CPU Ticks: \(snap.cpu.user + snap.cpu.system) | Mem: \(snap.memoryMB) MB | GPU: \(mlxMemory) bytes"
        print("[TELEMETRY-SNAPSHOT] \(name) => \(msg)")
        signposter.emitEvent(
            name,
            "CPU Ticks: \(snap.cpu.user + snap.cpu.system) | Mem: \(snap.memoryMB) MB | GPU: \(mlxMemory) bytes"
        )
    }
}

