import ArgumentParser
import Domain
import Foundation
import MLInfrastructure
import Utilities

// MARK: - Compare: MLX unconstrained vs XGrammar constrained

/// Runs both MLXSummarizationPlugin and XGrammarSummarizationPlugin on the same
/// transcript and shows a side-by-side comparison: timing, JSON validity, and summary content.
struct Compare: AsyncParsableCommand {
    static let configuration = CommandConfiguration(
        abstract: "Compare MLX (unconstrained) vs XGrammar (constrained) summarization on the same input"
    )

    @Argument(help: "Path to a WAV file, or a directory to run all WAVs inside it")
    var path: String

    @Option(name: .long, help: "Quality: fast (Parakeet), high (two-pass), max (WhisperKit only)")
    var quality: String = "fast"

    @Option(name: .long, help: "Summary model HF slug (default: gemma-4-e4b-it-4bit)")
    var model: String?

    @Option(name: .long, help: "Repeat each summarization N times to measure consistency")
    var runs: Int = 1

    func run() async throws {
        Term.banner()
        guard let q = Quality(rawValue: quality) else {
            Term.error("Invalid quality: \(quality). Use: fast, high, or max")
            throw ExitCode.failure
        }

        let inputURL = URL(fileURLWithPath: path)
        var wavFiles: [URL]

        if inputURL.hasDirectoryPath || (try? inputURL.resourceValues(forKeys: [.isDirectoryKey]).isDirectory) == true {
            wavFiles = try FileManager.default
                .contentsOfDirectory(at: inputURL, includingPropertiesForKeys: nil)
                .filter { $0.pathExtension == "wav" }
                .sorted { $0.lastPathComponent < $1.lastPathComponent }
        } else {
            guard FileManager.default.fileExists(atPath: inputURL.path) else {
                Term.error("File not found: \(path)")
                throw ExitCode.failure
            }
            wavFiles = [inputURL]
        }

        guard !wavFiles.isEmpty else {
            Term.error("No WAV files found at: \(path)")
            throw ExitCode.failure
        }

        // Load both plugins once — shared across all files
        let mlx = MLXSummarizationPlugin()
        let xgrammar = XGrammarSummarizationPlugin()
        let sumConfig = makeSummaryConfig(modelSlug: model)

        Term.info("Loading model", sumConfig.modelId.rawValue)
        let loadStart = CFAbsoluteTimeGetCurrent()
        try await mlx.loadModel(sumConfig)
        try await xgrammar.loadModel(sumConfig)
        Term.progressDone(CFAbsoluteTimeGetCurrent() - loadStart)

        // Transcribe + diarize once per file, then run both summarizers N times
        let runner = PipelineRunner()
        var rows: [CompareRow] = []

        for wav in wavFiles {
            Term.header("COMPARE: \(wav.lastPathComponent)")
            let result = try await runner.run(wavURL: wav, quality: q, skipSummary: true)
            let text = result.diarizedSegments
                .map { "[\($0.speakerId)] \($0.text)" }
                .joined(separator: "\n")
            let speakers = Array(Set(result.diarizedSegments.map(\.speakerId))).map(\.rawValue)

            Term.info("Duration", String(format: "%.1f min", result.audioSeconds / 60))
            Term.info("Transcript", "\(text.count) chars / ~\(text.count / 4) tokens (est)")

            var mlxTimes: [Double] = []
            var xgrammarTimes: [Double] = []
            var mlxValid = 0
            var xgrammarValid = 0
            var mlxSummary: MeetingSummary?
            var xgrammarSummary: MeetingSummary?

            for i in 1...runs {
                if runs > 1 { print("  Run \(i)/\(runs)") }

                // MLX unconstrained
                Term.progress("MLX (unconstrained)...")
                let t1 = CFAbsoluteTimeGetCurrent()
                if let s = try? await mlx.summarize(transcript: text, speakers: speakers) {
                    mlxTimes.append(CFAbsoluteTimeGetCurrent() - t1)
                    mlxValid += 1
                    mlxSummary = s
                    Term.progressDone(mlxTimes.last!)
                } else {
                    mlxTimes.append(CFAbsoluteTimeGetCurrent() - t1)
                    Term.progressDone(mlxTimes.last!)
                    Term.error("MLX failed (invalid JSON or error)")
                }

                // XGrammar constrained
                Term.progress("XGrammar (constrained)...")
                let t2 = CFAbsoluteTimeGetCurrent()
                if let s = try? await xgrammar.summarize(transcript: text, speakers: speakers) {
                    xgrammarTimes.append(CFAbsoluteTimeGetCurrent() - t2)
                    xgrammarValid += 1
                    xgrammarSummary = s
                    Term.progressDone(xgrammarTimes.last!)
                } else {
                    xgrammarTimes.append(CFAbsoluteTimeGetCurrent() - t2)
                    Term.progressDone(xgrammarTimes.last!)
                    Term.error("XGrammar failed")
                }
            }

            let row = CompareRow(
                file: wav.lastPathComponent,
                durationMin: result.audioSeconds / 60,
                runs: runs,
                mlxAvgTime: mlxTimes.reduce(0, +) / Double(mlxTimes.count),
                xgrammarAvgTime: xgrammarTimes.reduce(0, +) / Double(xgrammarTimes.count),
                mlxValidRate: Double(mlxValid) / Double(runs),
                xgrammarValidRate: Double(xgrammarValid) / Double(runs),
                mlxSummary: mlxSummary,
                xgrammarSummary: xgrammarSummary
            )
            rows.append(row)
            printRow(row)
        }

        printSummaryTable(rows)
        writeJSON(rows)
    }

    // MARK: - Helpers

    private func makeSummaryConfig(modelSlug: String?) -> SummaryConfig {
        guard let slug = modelSlug else { return SummaryConfig.default }
        return SummaryConfig(
            modelId: ModelID(slug),
            maxTokens: 2048,
            temperature: 0.3,
            enabled: true,
            meetingType: SummaryConfig.default.meetingType,
            contextWindow: SummaryConfig.default.contextWindow
        )
    }

    private func printRow(_ r: CompareRow) {
        Term.header("RESULTS: \(r.file)")
        let mlxTimeStr = String(format: "%.2fs", r.mlxAvgTime)
        let xgTimeStr = String(format: "%.2fs", r.xgrammarAvgTime)
        let speedup = r.mlxAvgTime / r.xgrammarAvgTime
        let speedupStr = String(format: "%.2f×", speedup)

        Term.metric("MLX time", "\(mlxTimeStr) — \(Int(r.mlxValidRate * 100))% valid JSON")
        Term.metric("XGrammar time", "\(xgTimeStr) — \(Int(r.xgrammarValidRate * 100))% valid JSON")
        Term.metric("Speed delta", speedup >= 1 ? "MLX \(speedupStr) faster" : "XGrammar \(speedupStr) faster")

        if let mlx = r.mlxSummary, let xg = r.xgrammarSummary {
            print("\n\(Term.bold)── MLX Summary ──────────────────────────────────\(Term.reset)")
            print(mlx.summary)
            print("\n\(Term.bold)── XGrammar Summary ─────────────────────────────\(Term.reset)")
            print(xg.summary)
            print("\n\(Term.bold)── Decisions ────────────────────────────────────\(Term.reset)")
            print("MLX:      \(mlx.decisions.count) decisions")
            print("XGrammar: \(xg.decisions.count) decisions")
            print("\(Term.bold)── Action Items ──────────────────────────────────\(Term.reset)")
            print("MLX:      \(mlx.actionItems.count) items")
            print("XGrammar: \(xg.actionItems.count) items")
        }
    }

    private func printSummaryTable(_ rows: [CompareRow]) {
        guard rows.count > 1 else { return }
        Term.header("SUMMARY TABLE")
        let header = String(format: "%-30s %8s %8s %8s %8s %6s %6s",
            "File", "Dur(m)", "MLX(s)", "XG(s)", "Δ(s)", "MLX%", "XG%")
        print(header)
        print(String(repeating: "─", count: 80))
        for r in rows {
            let delta = r.xgrammarAvgTime - r.mlxAvgTime
            let deltaStr = String(format: "%+.2f", delta)
            let row = String(format: "%-30s %8.1f %8.2f %8.2f %8s %5.0f%% %5.0f%%",
                String(r.file.prefix(30)),
                r.durationMin,
                r.mlxAvgTime,
                r.xgrammarAvgTime,
                deltaStr,
                r.mlxValidRate * 100,
                r.xgrammarValidRate * 100
            )
            print(row)
        }
        print(String(repeating: "─", count: 80))

        let avgMLX = rows.map(\.mlxAvgTime).reduce(0, +) / Double(rows.count)
        let avgXG = rows.map(\.xgrammarAvgTime).reduce(0, +) / Double(rows.count)
        let avgMLXValid = rows.map(\.mlxValidRate).reduce(0, +) / Double(rows.count)
        let avgXGValid = rows.map(\.xgrammarValidRate).reduce(0, +) / Double(rows.count)
        print(String(format: "%-30s %8s %8.2f %8.2f %8s %5.0f%% %5.0f%%",
            "AVERAGE", "",
            avgMLX, avgXG, "",
            avgMLXValid * 100, avgXGValid * 100))
    }
}

