import Domain
import DuckDB
import Foundation

extension DuckDBWriterActor {
    /// Persists a batch of InferenceMetrics entries to the inference_telemetry table.
    /// Skips entries that already exist (idempotent by id = modelId + timestamp).
    public func recordTelemetry(_ entries: [InferenceMetrics]) throws {
        for entry in entries {
            let id = "\(entry.modelId.rawValue)-\(entry.timestamp.timeIntervalSince1970)"
            let stmt = try prepared("""
                INSERT OR IGNORE INTO inference_telemetry
                (id, recorded_at, model_id, audio_seconds, inference_s, rtf,
                 confidence, sample_count, compute_unit,
                 cpu_pct, mem_mb, gpu_mb, page_faults,
                 os_version, cpu_brand, physical_mem_mb, thermal_state,
                 is_plugged_in, battery_pct)
                VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)
                """)
            let computeUnitStr: String
            switch entry.computeUnit {
            case .cpu: computeUnitStr = "cpu"
            case .ane: computeUnitStr = "ane"
            case .gpu: computeUnitStr = "gpu"
            case .cpuAndANE: computeUnitStr = "cpu_ane"
            case .cpuAndGPU: computeUnitStr = "cpu_gpu"
            }
            try stmt.bind(id, toParameter: 1)
            try stmt.bind(entry.timestamp.ISO8601Format(), toParameter: 2)
            try stmt.bind(entry.modelId.rawValue, toParameter: 3)
            try stmt.bind(entry.audioDuration, toParameter: 4)
            try stmt.bind(entry.inferenceDuration, toParameter: 5)
            try stmt.bind(entry.realTimeFactor, toParameter: 6)
            try stmt.bind(entry.confidence, toParameter: 7)
            try stmt.bind(Int32(entry.sampleCount), toParameter: 8)
            try stmt.bind(computeUnitStr, toParameter: 9)
            try stmt.bind(entry.processMetrics?.processCpuUtilization, toParameter: 10)
            let memMB = entry.processMetrics.map { $0.processMemoryUsage / 1_048_576 }
            try stmt.bind(memMB, toParameter: 11)
            let gpuMB = entry.processMetrics.map { $0.processMlxMemoryUsage / 1_048_576 }
            try stmt.bind(gpuMB, toParameter: 12)
            try stmt.bind(entry.processMetrics.map { Int32($0.processPageFaults) }, toParameter: 13)
            try stmt.bind(entry.environmentMetrics?.osVersion, toParameter: 14)
            try stmt.bind(entry.environmentMetrics?.cpuBrandString, toParameter: 15)
            try stmt.bind(entry.environmentMetrics.map { Int32($0.physicalMemoryMB) }, toParameter: 16)
            try stmt.bind(entry.environmentMetrics?.thermalState, toParameter: 17)
            try stmt.bind(entry.environmentMetrics?.isPluggedIn, toParameter: 18)
            try stmt.bind(entry.environmentMetrics.map { Int32($0.batteryStartPercentage) }, toParameter: 19)
            try stmt.run()
        }
    }
}
```

